UPDATE contract SET unit_id=NULL WHERE id IN (4,8,32,35,36,59,60,83,98,105,113,114,115,116,117,118,119,120,121,122,123,124,125,126,127,128,129,130,133,134,148,165,199,207,229,230,231,232,233,234,235,236,237,238,239,240,241,242,243,244,245,246,247,248,250,251,252,255,256,257,258,259,260,261,262,263,264,265,266,267,268,269,270,271,272,273,274,275,276,277,278,279,280,281,282,383,392);
UPDATE contract c JOIN building b ON b.id=c.building_id SET c.unit_id=NULL WHERE b.phase<>3 AND c.unit_id IS NOT NULL AND c.id IN (33,34,37,38,39,40,41,42,43,44,45,47,48,49,50,51,70,84,85,86,87,88,89,90,91,92,135,140,149,158,168,169,170,171,172,173,174,175,176,177,178,179,180,181,182,183,184,185,186,187,188,189,190,191,306);
UPDATE building b SET b.floor_count=GREATEST(b.floor_count, COALESCE((SELECT MAX(u.floor) FROM unit u WHERE u.building_id=b.id),1));
COMMIT;
